function catTile(title,sub,href,i){return '<a class="catTile" href="'+route(href)+'"><h3>'+tr(title)+'</h3><p>'+tr(sub)+'</p><div class="art">'+art(i)+'</div><span class="roundArrow">'+svg('arrow')+'</span></a>'}
function articleCard(title,sub,href){return '<article class="editorial"><span class="eyebrow">KAP. JOURNAL</span><h3>'+tr(title)+'</h3><p>'+tr(sub)+'</p><a href="'+route(href)+'" class="textlink">'+tr('discover')+' ↗</a></article>'}
function crumbs(parts){return '<div class="breadcrumbs"><a href="'+route('/')+'">'+tr('home')+'</a>'+parts.map(function(p){return '<span>/</span><span>'+p+'</span>'}).join('')+'</div>'}
function pagehead(title,subtitle,crumb){return '<section class="pagehead"><div class="container">'+crumbs(crumb||[title])+'<h1>'+title+'</h1>'+(subtitle?'<p>'+subtitle+'</p>':'')+'</div></section>'}
function catalog(key){var title={all:'allProducts',onderbouw:'underCabinet',recirculatie:'recirc',slimline:'slimline','60-cm':'width',zwart:'black',rvs:'stainless'}[key]||'allProducts';var list=PRODUCTS.filter(function(p){return key==='all'||key==='60-cm'||(key==='zwart'&&p.finish==='zwart')||(key==='rvs'&&p.finish==='rvs')||key===p.type});if(key==='recirculatie')list=[];if(ui.finish!=='all')list=list.filter(function(p){return p.finish===ui.finish});if(ui.sort==='asc')list.sort(function(a,b){return a.price-b.price});if(ui.sort==='desc')list.sort(function(a,b){return b.price-a.price});return '<main>'+pagehead(tr(title),tr('catSubtitle'),[tr('allProducts'),tr(title)])+'<section class="catalog"><div class="container catalogLayout"><aside class="sidefilters"><h3>'+tr('filterLabel')+'</h3><div class="filterGroup"><b>'+tr('category')+'</b>'+['all','onderbouw','slimline','recirculatie','60-cm'].map(function(k){return '<a class="'+(k===key?'active':'')+'" href="'+route('/afzuigkappen/'+(k==='all'?'':k+'/'))+'">'+tr({all:'allProducts',onderbouw:'underCabinet',slimline:'slimline',recirculatie:'recirc','60-cm':'width'}[k])+'</a>'}).join('')+'</div><div class="filterGroup"><b>'+tr('finish')+'</b><label><input type="radio" name="finish" value="all" '+(ui.finish==='all'?'checked':'')+'>'+tr('all')+'</label><label><input type="radio" name="finish" value="zwart" '+(ui.finish==='zwart'?'checked':'')+'>'+tr('black')+'</label><label><input type="radio" name="finish" value="rvs" '+(ui.finish==='rvs'?'checked':'')+'>'+tr('stainless')+'</label></div></aside><div><div class="catalogTop"><strong>'+list.length+' '+tr('results')+'</strong><select aria-label="'+tr('sort')+'" id="sort"><option value="recommended" '+(ui.sort==='recommended'?'selected':'')+'>'+tr('recommended')+'</option><option value="asc" '+(ui.sort==='asc'?'selected':'')+'>'+tr('priceLow')+'</option><option value="desc" '+(ui.sort==='desc'?'selected':'')+'>'+tr('priceHigh')+'</option></select><div class="mobileOnly mobileFilters"><label for="mobileFinish">'+tr('finish')+'</label><select id="mobileFinish"><option value="all" '+(ui.finish==='all'?'selected':'')+'>'+tr('all')+'</option><option value="zwart" '+(ui.finish==='zwart'?'selected':'')+'>'+tr('black')+'</option><option value="rvs" '+(ui.finish==='rvs'?'selected':'')+'>'+tr('stainless')+'</option></select></div></div>'+(list.length?'<div class="productGrid catalogGrid">'+list.map(productCard).join('')+'</div>':'<div class="emptyState"><h2>'+tr('emptyResults')+'</h2><a class="btn ghost" href="'+route('/afzuigkappen/')+'">'+tr('tryOther')+'</a></div>')+'</div></div></section></main>'}
