var intro='<div class="proInfoLead"><div><span class="eyebrow">'+(nl?'DE JUISTE KEUZE':'MAKE THE RIGHT CHOICE')+'</span><h2>'+(nl?'Een afzuigkap kies je niet alleen op design.':'More than just good looks.')+'</h2><p>'+(nl?'Controleer de montageplek, de afmetingen en of jouw keuken luchtafvoer of recirculatie nodig heeft. Voor dit voorbeeldmodel zijn afzuigcapaciteit, geluidsniveau en filters nog niet bevestigd.':'Check fitting dimensions and whether your kitchen needs extraction or recirculation. Airflow, noise and filters have not been verified for this example model.')+'</p><a class="textlink" href="'+route('/advies/maat-kiezen/')+'">'+(nl?'Lees de maatkeuzehulp':'Read the sizing guide')+' ↗</a></div><div class="proInstall"><span class="smallcaps">'+(nl?'VOOR JE BESTELT':'BEFORE YOU ORDER')+'</span><h3>'+(nl?'Drie checks voor je keuken':'Three checks for your kitchen')+'</h3><ul><li>'+(nl?'De beschikbare breedte en diepte':'Available width and depth')+'</li><li>'+(nl?'De minimale montageafstand':'Minimum installation clearance')+'</li><li>'+(nl?'De juiste afvoer- of filteropstelling':'Correct duct or filter setup')+'</li></ul></div></div>';
